    /// <param name="printer"></param>
    /// <param name="dataContract"></param>
    /// <param name="result"></param>
    [SubscribesTo(classStr(SRSPrintDestinationSettingsDelegates), delegateStr(SRSPrintDestinationSettingsDelegates, toEmailSucceed))]
    public static void SRSPrintDestinationSettingsDelegates_toEmailSucceed(SrsReportRunPrinter printer, SrsReportDataContract dataContract, EventHandlerResult result)
    {
        if(dataContract.parmRdpContract() is PurchPurchaseOrderContract)
        {
            PurchPurchaseOrderContract  purchConfirmContract  = dataContract.parmRdpContract() as PurchPurchaseOrderContract;
            VendPurchOrderJour          vendPurchOrderJourn = VendPurchOrderJour::findRecId(purchConfirmContract.parmRecordId());

            vendPurchOrderJourn.purchTable().metPurchTable().updatePOSentFlag();

        }
    }
